import random
import os
import string
from typing import List

# This generator targets FUZZ_PARAM_STR for ngx_http_headers_more_hash_str.
# We aim to produce interesting byte sequences that exercise different hashing behaviors
# while remaining valid arbitrary buffers. No specific structure is required by the target.

MAX_SIZE = 4096

def _rand_ascii(r: random.Random, length: int) -> bytes:
    # Mix of visible ASCII including separators
    chars = string.ascii_letters + string.digits + string.punctuation + " \t\r\n"
    return ''.join(r.choice(chars) for _ in range(length)).encode('utf-8', 'ignore')

def _repeated_byte(r: random.Random, length: int) -> bytes:
    b = r.randrange(0, 256)
    return bytes([b]) * length

def _incrementing_bytes(start: int, length: int) -> bytes:
    return bytes(((start + i) % 256) for i in range(length))

def _decrementing_bytes(start: int, length: int) -> bytes:
    return bytes(((start - i) % 256) for i in range(length))

def _zeroes(length: int) -> bytes:
    return b"\x00" * length

def _utf8_like(r: random.Random, length: int) -> bytes:
    # Construct UTF-8 sequences (valid) mixed with ASCII
    out = bytearray()
    while len(out) < length:
        choice = r.random()
        if choice < 0.5:
            out.append(r.randrange(0x20, 0x7F))
        elif choice < 0.7:
            # 2-byte
            cp = r.randrange(0x80, 0x7FF)
            out.extend(chr(cp).encode('utf-8'))
        elif choice < 0.9:
            # 3-byte
            cp = r.randrange(0x800, 0xFFFF)
            out.extend(chr(cp).encode('utf-8', 'ignore'))
        else:
            # 4-byte (excluding surrogate range)
            cp = r.randrange(0x10000, 0x10FFFF)
            out.extend(chr(cp).encode('utf-8'))
        if len(out) > length:
            del out[length:]
    return bytes(out)

def _binary_chunks(r: random.Random, length: int) -> bytes:
    # Mix random bytes with structured patterns
    parts: List[bytes] = []
    remaining = length
    patterns = [
        lambda n: os.urandom(n),
        lambda n: _repeated_byte(r, n),
        lambda n: _incrementing_bytes(r.randrange(0, 256), n),
        lambda n: _decrementing_bytes(r.randrange(0, 256), n),
        lambda n: _zeroes(n),
        lambda n: _rand_ascii(r, n),
        lambda n: _utf8_like(r, n),
    ]
    while remaining > 0:
        chunk = r.randrange(1, min(256, remaining) + 1)
        gen = r.choice(patterns)
        parts.append(gen(chunk))
        remaining -= chunk
    return b"".join(parts)

def _palindrome(r: random.Random, length: int) -> bytes:
    half = (length + 1) // 2
    left = os.urandom(half)
    if length % 2 == 0:
        return left + left[::-1]
    else:
        return left + left[-2::-1]

def _edge_seeds() -> List[bytes]:
    # Common header-like seeds to exercise ASCII and token hashing
    seeds = [
        b"",  # n may be 0 in harness; empty buffer still useful
        b"Host",
        b"host",
        b"Content-Type",
        b"content-type",
        b"Set-Cookie",
        b"User-Agent",
        b"Accept-Encoding",
        b"X-Forwarded-For",
        b"Transfer-Encoding",
        b"TE",
        b"ETag",
        b"etag",
        b"Cache-Control",
        b"Authorization",
        b"\x00",  # includes NUL
        b"\xff\x00\xff\x00",
    ]
    return seeds

def _compose_interesting(r: random.Random, target_len: int) -> bytes:
    # Select a strategy based on seed to vary outputs deterministically
    strat = r.randrange(0, 9)
    if strat == 0:
        # Pure random bytes
        return os.urandom(target_len)
    if strat == 1:
        return _binary_chunks(r, target_len)
    if strat == 2:
        return _rand_ascii(r, target_len)
    if strat == 3:
        return _utf8_like(r, target_len)
    if strat == 4:
        return _repeated_byte(r, target_len)
    if strat == 5:
        return _incrementing_bytes(r.randrange(0, 256), target_len)
    if strat == 6:
        return _decrementing_bytes(r.randrange(0, 256), target_len)
    if strat == 7:
        return _palindrome(r, target_len)
    # strat == 8: concatenate seeds and random tail
    seeds = _edge_seeds()
    prefix = r.choice(seeds)
    if len(prefix) >= target_len:
        return prefix[:target_len]
    tail = _binary_chunks(r, target_len - len(prefix))
    return prefix + tail

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose size: bias towards small sizes with occasional larger ones up to MAX_SIZE
    roll = r.random()
    if roll < 0.15:
        size = 0  # empty buffer; harness may still choose n>0? It guards n<=size.
    elif roll < 0.55:
        size = r.randint(1, 64)
    elif roll < 0.9:
        size = r.randint(65, 512)
    else:
        size = r.randint(513, MAX_SIZE)

    # Occasionally return a well-known header token exactly
    if r.random() < 0.25 and size >= 2:
        seed_bytes = r.choice(_edge_seeds())
        if len(seed_bytes) == 0 and size > 0:
            # regenerate if zero-length but we want a token
            seed_bytes = b"Host"
        if len(seed_bytes) >= size:
            return seed_bytes[:size]
        # pad with structured tail to reach size
        tail = _compose_interesting(r, size - len(seed_bytes))
        return seed_bytes + tail

    return _compose_interesting(r, size)
